function crear(){const c=sel||'abarrotes',v=id=>($('#'+id)?.value||'').trim();let det={};
 if(view==='carrito'){const st=store(shop),it=cartItems();if(!it.length&&!v('extra'))return toast('Agrega productos al carrito');
  det={storeId:st.id,tienda:st.n,items:it.map(i=>({n:i.n,pres:i.pres,p:i.p,q:i.q,pc:i.pc,pid:i.id})),notas:v('notaT'),extra:v('extra'),extraEst:+v('extraEst')||0,receta:!!$('#receta')?.files.length}}else{
 if(c!=='paquetes')return toast('Elige una tienda y agrega productos del catálogo');
 if(c==='paquetes')det={de:v('de'),a:v('a'),tam:v('tam')};
 }
 const miss=det.items?false:(c==='paquetes'?!det.de||!det.a:true);
 if(miss)return toast('Completa los datos del pedido');{const a=acct(),x=a?sancSt('cli:'+a.email):sancSt('inv:'+v('tel').replace(/\D/g,''));if(x)return toast(a?sancMsg(x):'Este número de teléfono está bloqueado. No puede pedir como invitado.')}if(!v('nom'))return toast('Escribe el nombre de quien recibe');if(!/^\d{10}$/.test(v('tel').replace(/\D/g,'')))return toast('Escribe un teléfono de 10 dígitos');if(!v('dir'))return toast('Escribe la dirección de entrega');
 if(det.items){const st=store(det.storeId),bad=det.items.map(i=>[i,st.prods.find(p=>p.id===i.pid)]).find(([i,p])=>!p||!avail(p)||(p.stk!=null&&i.q>p.stk));if(bad){const [i,p]=bad;if(p&&p.stk!=null&&p.stk>0)cart[p.id]=p.stk;else if(p)delete cart[p.id];render();return toast(p&&avail(p)?'Solo quedan '+p.stk+' de '+i.n+'. Ajustamos tu carrito.':i.n+' se acaba de agotar. Lo quitamos de tu carrito.')}}
 const pago=document.querySelector('[name=pago]:checked').value,a0=acct(),L0=cards();let tj=null;
 if(a0&&L0.length){if(pago!=='tarjeta')return toast('Tienes una tarjeta registrada: el pago se hace con tarjeta');tj=L0.find(c=>c.id==($('#tsel')?.value||L0[0].id))||L0[0]}
 else if(pago==='tarjeta'){const c=readCard('k');if(!c)return;tj=a0?saveTarj(c):c}
 const o={id:Math.max(...DB.orders.map(x=>x.id),1000)+1,cat:c,det,dir:v('dir'),tel:v('tel'),zona:+v('zona'),fee:feeNow(),pago,pagaCon:pago==='efectivo'?+v('pagaCon')||0:0,st:0,rep:'',cobrado:0,t:Date.now(),ts:{0:Date.now()},d:today(),senas:($('#senas')?.value||'').trim(),nombre:v('nom'),src:acct()?'cuenta':'invitado',email:acct()?.email||''};if(tj)o.tarj={marca:tj.marca,last4:tj.last4};o.tel=o.tel.replace(/\D/g,'');
 if(det.items)stkTake(o);DB.orders.push(o);DB.mine.push(o.id);save();if(det.items){cart={};shop=null}track=o.id;toast(pago==='tarjeta'?'Pedido enviado (pago demo, sin cargo)':'¡Pedido enviado!');go('track')}

const R={home:()=>{const mine=DB.orders.filter(o=>o.rep===myRep&&!done(o)),av=DB.orders.filter(o=>!o.rep&&!done(o)&&ACTIVE.includes(o.cat)),fin=DB.orders.filter(o=>o.rep===myRep&&done(o)&&o.d===today());
 const cash=fin.filter(o=>o.pago==='efectivo'&&o.cobrado).reduce((a,o)=>a+total(o),0);
 const sx=sancSt('rep:'+myRep),vok=repOk(myRep);return `${regBanner()}${sx?blockedView(sx,'Repartidor suspendido')+'<div class="warn">No puedes aceptar pedidos nuevos.</div>':''}<div class="card">${SYNC}<div class="row"><b>🛵 ${esc(myRep)} ${regTag(myRep)}</b><button class="btn sec sm" style="margin:0" onclick="logout()">Salir</button></div><div class="muted" style="margin-top:6px">Entregados hoy: ${fin.length} · Efectivo cobrado hoy: ${mx(cash)} (se descuenta de tu pago semanal)</div></div>
 <h3>Mis pedidos asignados</h3>${mine.map(o=>repCard(o,`<div class="muted">Estado actual: <b>${stName(o)}</b></div>${repStoreSt(o)}${advBtn(o)}<button class="btn sec sm" onclick="oSel=${o.id};go('pedido')">💬 Chat${o.det.items?' y artículos':''}</button>`)).join('')||'<p class="muted">Sin pedidos asignados.</p>'}
 <h3>Disponibles</h3>${vok?av.map(o=>repCard(o,`${repPayHint(o)}<button class="btn sm" onclick="tomar(${o.id})">✅ Aceptar pedido</button>`)).join('')||'<p class="muted">No hay pedidos disponibles.</p>':`<div class="card" id="nodisp"><p class="muted">🔒 Hay ${av.length} pedido${av.length===1?'':'s'} disponible${av.length===1?'':'s'}. Podrás ver los datos del cliente y aceptarlos cuando aprueben tu registro.</p></div>`}
 <h3>Entregados hoy</h3>${fin.map(o=>repCard(o,(o.pago==='efectivo'?(o.cobrado?'<span class="tag ok">💵 Efectivo cobrado (es tuyo; se descuenta de tu pago semanal)</span>':`<label>¿Cuánto cobraste? (total sin el cambio, debe ser ${mx(total(o))})</label><input id="cm${o.id}" type="number" inputmode="decimal" value="${total(o)}"><button class="btn sm" onclick="cobrar(${o.id})">💵 Marcar efectivo cobrado</button>`):'<span class="tag ok">💳 Pagado con tarjeta – no cobraste nada</span>')+`<div class="muted" style="margin-top:6px">💰 Tu ganancia: <b>${mx(earn(o))}</b> (${pctOf(o)}% de ${mx(o.fee)} de envío)</div>`+((o.chat||[]).length?`<button class="btn sec sm" onclick="oSel=${o.id};go('pedido')">💬 Ver chat</button>`:''))).join('')||'<p class="muted">Aún nada.</p>'}${bioCard()}`}};
const O=id=>DB.orders.find(o=>o.id===id);
// v18: vista del repartidor sin precios (solo artículos, cliente, domicilio, señas, tienda, folio, estado)
const mapUrl=d=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent((d||'')+', Tuxpan, Nayarit');
function repSum(o){const d=o.det;if(d.items)return `<div class="repitems">🏪 <b>Recoger en: ${esc(d.tienda)}</b>${o.nota?` · Nota <b>${esc(o.nota.folio)}</b>`:''}<br>`+d.items.map(i=>`• ${i.quit?'<s>':''}${i.q} × ${esc(i.n)} (${esc(i.pres)})${i.quit?'</s> <span class="tag bad">Quitado</span>':i.res==='cambiar'?' <span class="tag ex">🔁 Cambiar por similar</span>':i.na?' <span class="tag ex">⚠️ No disponible</span>':''}`).join('<br>')+(d.extra?`<br>• Extra: ${esc(d.extra)}`:'')+(d.receta?'<br>📷 Receta adjunta':'')+'</div>';
 return o.cat==='paquetes'?`De: ${esc(d.de)} → A: ${esc(d.a)} (${esc(d.tam)})`:o.cat==='servicios'?`${esc(d.tipo)} · Ref ${esc(d.ref)}`:esc(d.lista).replace(/\n/g,', ')+(d.tienda?` · ${esc(d.tienda)}`:'')+(d.receta?' · 📷 receta':'')}
const repCard=(o,extra='')=>`<div class="card repcard" data-rc="${o.id}"><div class="row"><b>${CATS[o.cat][0]} #${o.id} ${CATS[o.cat][1]}</b><span>${tag(o)}${bdg(o)}</span></div>
<div class="muted">${repSum(o)}</div><div class="muted" style="margin-top:6px">👤 <b>${esc(o.nombre||'Cliente')}</b> · 📞 <a href="tel:${esc(o.tel)}">${esc(o.tel)}</a></div><div class="muted">📍 ${esc(o.dir)} · <a class="maplink" href="${mapUrl(o.dir)}" target="_blank" rel="noopener">🗺️ Ver en mapa</a></div>${o.senas?`<div class="muted repsenas">🏠 <b>Señas del domicilio:</b> ${esc(o.senas)}</div>`:''}${extra}</div>`;
function tomar(id){if(!repOk(myRep))return toast('Tu registro aún no está aprobado: no puedes aceptar pedidos');const x=sancSt('rep:'+myRep);if(x)return toast('Estás suspendido: no puedes aceptar pedidos');O(id).rep=myRep;save();toast('Pedido aceptado');render()}
function adv(id){const o=O(id);if(needRec(o))return toast('Primero registra la recolección con la foto del ticket');o.st=Math.min(o.st+1,steps(o).length-1);o.ts=o.ts||{0:o.t};o.ts[o.st]=Date.now();if(o.st===steps(o).length-1&&!o.cancel&&o.pct==null)o.pct=repPct();save();toast('Estado: '+stName(o));render()}
function cobrar(id){const o=O(id),m=+($('#cm'+id)?.value||0);if(!m)return toast('Escribe cuánto cobraste (sin contar el cambio)');o.cobrado=1;o.cobradoMonto=m;save();toast(overch(o)?'⚠️ Registrado: el cobro es mayor al total del pedido':'Efectivo registrado');render()}


