const CRNOTE='<div class="warn">Versión de prueba: el crédito y los pagos a tiendas solo se registran en este celular hasta conectar el servidor. La app no paga a las tiendas.</div>';
const crOf=id=>{DB.credito=DB.credito||{};return DB.credito[id]||(DB.credito[id]={lim:0,cargos:[],pagos:[]})};
