// ================= PRECIOS REALES, REVISIÓN DE PRECIOS Y TABLET DE TIENDA (v10) =================
// Cada producto: p = precio de venta (lo que paga el cliente), pc = precio de compra (lo que la tienda le cobra a la empresa),
// pcEst = compra estimada (migración), rev = revisado, upd = {t,por}. Cada tienda: revT/revPor (última revisión de precios), tab (código de tablet, solo hash).
// Compra y margen solo se muestran en Dueño y Directivo. La tienda solo ve su propio precio (compra). Cliente y repartidor solo ven el precio de venta.
function addV10(d){d.dirCfg=d.dirCfg||{tarde:60};if(d.dirCfg.precDias==null)d.dirCfg.precDias=7;if(d.dirCfg.ocultarVenc==null)d.dirCfg.ocultarVenc=false;d.tReq=d.tReq||[];
 (d.stores||[]).forEach(s=>{if(s.revT===undefined){s.revT=null;s.revPor=''}if(s.tab===undefined)s.tab=null;(s.prods||[]).forEach(p=>{if(p.pc==null){p.pc=Math.round((+p.p||0)*0.85*100)/100;p.pcEst=1;p.rev=0;p.upd=null}})})}
const TNOTE='';
const PRNOTE='<div class="warn">Versión de prueba: los precios, revisiones y códigos de tablet solo se guardan en este celular hasta conectar el servidor.</div>';
const precN=()=>(DB.dirCfg&&DB.dirCfg.precDias)||7;
const revDays=s=>s.revT?Math.floor((Date.now()-s.revT)/864e5):null;
const vencido=s=>s.revT==null||revDays(s)>precN();
const ocultaSt=s=>!!(DB.dirCfg&&DB.dirCfg.ocultarVenc)&&(s.revT==null||revDays(s)>2*precN());
const dTxt=n=>n===0?'hoy':'hace '+n+' día'+(n===1?'':'s');
const revTxt=s=>s.revT?`Última revisión de precios: ${fdt(s.revT)} (${dTxt(revDays(s))})${s.revPor?' · Por '+esc(s.revPor):''}`:'Última revisión de precios: nunca';
const vencTag=s=>vencido(s)?`<span class="tag bad">⚠️ Precios vencidos${s.revT?' · '+revDays(s)+' días':' · sin revisar'}</span>`:'<span class="tag ok">✅ Precios al día</span>';
const mrg=p=>r2((+p.p||0)-(+p.pc||0)), mrgPct=p=>+p.p?Math.round(mrg(p)/p.p*100):0;
const mrgSug=()=>{const m=DB.dirCfg&&DB.dirCfg.mrgSug;return m==null?10:+m};
const sugNew=pc=>{pc=+pc||0;return pc>0?Math.max(pc,Math.round(pc*(1+mrgSug()/100)*2)/2):0};
const mrgTxt=p=>`<span class="mrg ${mrg(p)<0?'negt':'okt'}">Margen ${mx(mrg(p))} (${mrgPct(p)}%)</span>`;
const porQ=()=>role==='dir'?'Directivo':role==='tienda'?'Tienda':'Dueño';
const tReqs=(sid,st='pendiente')=>(DB.tReq||[]).filter(r=>(sid==null?!!store(r.storeId):r.storeId===sid)&&(!st||r.st===st)&&(st!=='pendiente'||r.tipo!=='precio')); // v11: los cambios de precio ya no esperan aprobación
const treqCount=()=>tReqs(null).length;
const stamp=(p,por)=>{p.upd={t:Date.now(),por};p.rev=1};
const updTxt=p=>p.upd?`Actualizado ${fdt(p.upd.t)} · ${esc(p.upd.por)}`:'Sin revisar';
const pThumb=p=>p.foto?`<img class="pimg" data-pfoto="${esc(p.foto)}" data-emo="${esc(p.e||'🛍️')}" alt="">`:`<div class="emo">${p.e||'🛍️'}</div>`;
let tq='',tf='todos',tFoto=null,tDraft={},rv=null,rvD={},rvFoto=null,tabShow=null,openTab={},dSt=null,dBack=null,trBack=null;
function pfill(){document.querySelectorAll('img[data-pfoto]').forEach(im=>{if(im.dataset.ok)return;im.dataset.ok=1;fget(im.dataset.pfoto).then(v=>{if(v)im.src=v;else im.replaceWith(Object.assign(document.createElement('div'),{className:'emo',textContent:im.dataset.emo||'🛍️'}))}).catch(()=>{})})}
{const _a=afterR;afterR=function(){_a();pfill()}}
function pEd(k,i,f,v){const p=DB.stores[k]&&DB.stores[k].prods[i];if(!p)return;if((f==='pc'||f==='p')&&!(v>=0)){toast('Precio no válido');render();return}p[f]=v;if(f==='pc')p.pcEst=0;if(f==='pc'&&!(+p.p>0)&&v>0){p.p=sugNew(v);toast('Precio de venta sugerido: '+mx(p.p)+' ('+mrgSug()+'%)')}if(['pc','p','disp'].includes(f))stamp(p,porQ());save();if(f==='pc'||f==='p'){if(mrg(p)<0&&p.p)toast('⚠️ El precio de venta es menor que el de compra');render()}}
