TV.home=()=>TV.prods();
function tPrice(pid){const s=myStore();if(!s)return render();const p=s.prods.find(x=>x.id===pid),v=r2(+gv('tp'+pid));if(!p)return;if(!(v>0))return toast('Escribe un precio válido');
 const c=applyPc(DB,s,p,v,'Tienda (tablet)');touch(s);save();toast((c.big?'⚠️ Cambio grande: se aplicó y el dueño lo revisará. ':'Listo. ')+'El cliente ya ve '+mx(c.newP));render()}
function tConfirm(){const s=myStore();if(!s)return render();if(!confirm('¿Confirmas que todos los precios de '+s.n+' están al día? Esto cuenta como revisión de precios por '+precN()+' días.'))return;const t=Date.now();s.revT=t;s.revPor='Tienda';touch(s);DB.audit.push({t,key:'tienda:'+s.n,acc:'Precios confirmados por la tienda',mot:'',nota:s.prods.length+' productos · Por Tienda (tablet)'});save();toast('¡Gracias! Tus precios quedaron confirmados');render()}
function tDisp(pid){const s=myStore();if(!s)return render();const p=s.prods.find(x=>x.id===pid);if(!p)return;const t=Date.now();p.disp=p.disp?0:1;p.upd={t,por:'Tienda'};touch(s);DB.audit.push({t,key:'tienda:'+s.n,acc:p.disp?'Tablet: producto disponible':'Tablet: producto agotado',mot:'',nota:p.n+' ('+p.pres+')'});save();toast(p.disp?'Marcado como disponible':'Marcado como agotado: los clientes ya no lo pueden pedir');render()}
async function tFile(inp){const f=inp.files[0];if(!f)return;tDraft={n:gv('tn'),pr:gv('tpr'),pp:gv('tpp')};try{tFoto=await shrink(f,700,.8)}catch(e){toast('No se pudo leer la foto')}render()}
async function tReqNew(){const s=myStore();if(!s)return render();const n=gv('tn').trim(),pr=gv('tpr').trim(),v=r2(+gv('tpp'));if(!n)return toast('Escribe el nombre del producto');if(!pr)return toast('Escribe la presentación');if(!(v>0))return toast('Escribe tu precio');
 const id=Math.max(0,...DB.tReq.map(z=>z.id))+1,t=Date.now();let foto=null;if(tFoto){foto='preq:'+((myStore()||{}).id||0)+':'+id+':'+t;try{await fput(foto,tFoto)}catch(e){foto=null}}
 DB.tReq.push({id,storeId:s.id,tipo:'nuevo',n,pres:pr,nuevo:v,foto,st:'pendiente',t,por:'Tienda'});touch(s);DB.audit.push({t,key:'tienda:'+s.n,acc:'Tablet: producto nuevo solicitado',mot:'',nota:`${n} (${pr}) · ${mx(v)}`});tFoto=null;tDraft={};save();toast('Solicitud enviada al dueño');render()}
function tReady(id){const s=myStore(),o=O(id);if(!s||!o||o.det.storeId!==s.id||o.prep||o.compra||done(o))return;if(!o.nota)return toast('Primero genera la nota de remisión');notaFreeze(o);const t=Date.now();o.prep={t};o.chat=o.chat||[];o.chat.push({id:o.chat.reduce((a,m)=>Math.max(a,m.id||0),0)+1,de:'sys',kind:'sys',who:'Tienda',t,txt:'🏪 '+s.n+' avisa: el pedido está listo para recoger.'});touch(s);save();toast('Listo. Se le avisó al repartidor.');render()}
