function cliStoreBan(o){if(o.cancel||!o.det.items||done(o))return '';if(o.recog)return `<div class="okbox" id="recogban">📦 <b>Pedido recogido.</b> Tu pedido fue recogido en ${esc(o.det.tienda)} por ${esc(o.rep||'el repartidor')} a las ${hm(o.recog.t)}, va en camino.</div>`;
 if(o.prep)return '<div class="okbox" id="tiendaban">🏪 Tu pedido ya está listo en la tienda; el repartidor va por él.</div>';if(o.tacc)return '<div class="okbox" id="tiendaban">🏪 La tienda aceptó tu pedido y lo está surtiendo.</div>';return ''}
function repStoreSt(o){if(!o.det||!o.det.items||done(o))return '';const s=store(o.det.storeId),tab=s&&s.tab&&s.tab.act;
 if(o.compra)return o.recog&&o.recog.tienda&&o.recog.rep?'<div class="muted repst">🤝 Entrega confirmada por la tienda y por ti.</div>':'';
 if(o.prep)return `<div class="okbox repst" id="replisto">✅ <b>Listo para recoger</b> en ${esc(o.det.tienda)}${o.nota?` · Nota <b class="rfolio">${esc(o.nota.folio)}</b>`:''}. Pide la nota de remisión, fírmala y tómale foto.${o.recog&&o.recog.tienda?' <br>🏪 La tienda ya marcó que te lo entregó: confirma con la foto de la nota.':''}</div>`;
 if(o.tacc)return '<div class="warn repst" id="repespera">⏳ <b>Esperando a la tienda</b> · están surtiendo el pedido.</div>';
 return tab?'<div class="warn repst" id="repespera">⏳ <b>Esperando a la tienda</b> · aún no acepta el pedido.</div>':''}
// ---- seguimiento en vivo (dueño / directivo)
function tline(o){const P=o.cat==='paquetes',ts=o.ts||{},L=[['Recibido',o.t]];if(o.det&&o.det.items){L.push(['Aceptado por la tienda',o.tacc&&o.tacc.t]);L.push(['Listo para recoger',o.prep&&o.prep.t])}
 L.push(['Recogido',o.recog?o.recog.t:o.compra&&o.compra.t]);L.push(['En camino',ts[P?2:3]]);L.push(['Entregado',ts[P?3:4]]);return L.map(([l,t])=>[l,t||null])}
const durTxt=ms=>{const m=Math.max(0,Math.round(ms/6e4));return m<60?m+' min':Math.floor(m/60)+' h '+(m%60)+' min'};
const curStep=o=>{if(o.cancel)return 'Cancelado';const L=tline(o).filter(x=>x[1]);return L.length?L[L.length-1][0]:'Recibido'};
function tlHtml(o){let prev=null;return `<ul class="tl">${tline(o).map(([l,t])=>{const h=t?`<li class="done" data-step="${esc(l)}"><b>${l}</b> <span class="muted">${hm(t)}${prev?' · +'+durTxt(t-prev):''}</span></li>`:`<li data-step="${esc(l)}">${l} <span class="muted">pendiente</span></li>`;if(t)prev=t;return h}).join('')}</ul>`}
const tlCard=o=>`<div class="card" id="tlcard"><h3>⏱️ Tiempos por paso</h3>${tlHtml(o)}${!done(o)?`<div class="muted">En curso desde hace ${durTxt(Date.now()-o.t)}</div>`:durMin(o)!=null?`<div class="muted">Total: ${durMin(o)} min</div>`:''}</div>`;
const vivoAct=()=>DB.orders.filter(o=>!done(o)&&ACTIVE.includes(o.cat)).sort((a,b)=>b.t-a.t);
function vivoEvents(n){const E=[];DB.orders.forEach(o=>tline(o).forEach(([l,t])=>{if(t)E.push({o,l,t})}));return E.sort((a,b)=>b.t-a.t).slice(0,n)}
const evTxt=e=>{const o=e.o;return {'Recibido':`🆕 Pedido #${o.id} recibido`,'Aceptado por la tienda':`🏪 #${o.id} aceptado por ${o.det.tienda||'la tienda'}`,'Listo para recoger':`✅ #${o.id} listo para recoger en ${o.det.tienda||'la tienda'}`,'Recogido':o.det.items?`📦 #${o.id} recogido en ${o.det.tienda} por ${o.rep||'repartidor'}`:`📦 #${o.id} paquete recogido por ${o.rep||'repartidor'}`,'En camino':`🛵 #${o.id} en camino`,'Entregado':`🎉 #${o.id} entregado`}[e.l]||('#'+o.id+' '+e.l)};
const evRow=e=>`<div class="row line ev"><span>${esc(evTxt(e))}</span><span class="muted">${hm(e.t)}</span></div>`;
function vivoLink(){const A=vivoAct(),E=vivoEvents(3);return `<div class="card store" id="vivolink" onclick="go('vivo')"><div class="row"><b>🛰️ Seguimiento en vivo</b><span class="tag ${A.length?'ex':''}">${A.length} activo${A.length===1?'':'s'}</span></div>${E.map(evRow).join('')||'<div class="muted">Sin movimientos.</div>'}<div class="muted" style="text-align:right">Ver todos ›</div></div>`}
function vivoView(){const L=vivoAct();return `${dkBack('home')}<h2>🛰️ Seguimiento en vivo</h2><button class="btn sm" id="mapbtn" onclick="MP.sel=null;go('mapa')">🗺️ Mapa de repartidores y tiendas</button><div class="muted">Pedidos activos con su paso actual y el tiempo de cada paso. Se actualiza solo.</div>
 <div id="vlist">${L.map(o=>`<div class="card vivo" data-vo="${o.id}"><div class="row"><b>${CATS[o.cat][0]} #${o.id}${o.det.tienda?' · '+esc(o.det.tienda):''}</b><span class="tag ex vstep">${curStep(o)}</span></div><div class="muted">🛵 ${o.rep?esc(o.rep):'Sin repartidor'} · Recibido hace ${durTxt(Date.now()-o.t)}</div>${tlHtml(o)}${role==='dir'?`<button class="btn sec sm" onclick="oSel=${o.id};oBack=null;go('pedido')">Ver pedido ›</button>`:''}</div>`).join('')||'<p class="muted">No hay pedidos activos.</p>'}</div>
 <div class="card" id="vfeed"><h3>Últimos movimientos</h3>${vivoEvents(15).map(evRow).join('')||'<p class="muted">Sin movimientos.</p>'}</div>`}
A.vivo=vivoView;D.vivo=vivoView;
// ---- avisos en vivo (tablet: nuevo pedido; dueño/directivo: movimientos)
let vivoSeen=null;
function beep(){try{if(!(navigator.userActivation&&navigator.userActivation.hasBeenActive))return;const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const a=new C(),o=a.createOscillator(),g=a.createGain();o.frequency.value=880;g.gain.value=.15;o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.35);setTimeout(()=>a.close(),700);if(navigator.vibrate)navigator.vibrate([200,100,200])}catch(e){}}
function liveNotify(){if(role==='tienda'){let b=$('#tnewban');const s=tSessOk()&&myStore();const N=s?tOrders(s).filter(o=>!o.tacc&&!o.prep&&!tPk(o)&&!done(o)).sort((a,b)=>b.t-a.t):[];
  let K=[];try{K=JSON.parse(sessionStorage.getItem('tienda_known')||'[]')}catch(e){}const fresh=N.filter(o=>!K.includes(o.id));if(fresh.length){beep();sessionStorage.setItem('tienda_known',JSON.stringify(K.concat(fresh.map(o=>o.id))));tBanOff=tBanOff.filter(id=>!fresh.some(o=>o.id===id))}
  const V=N.filter(o=>!tBanOff.includes(o.id));if(!V.length){if(b)b.remove();return}if(!b){b=document.createElement('div');b.id='tnewban';b.className='tnew';document.body.appendChild(b)}const o=V[0],n=o.det.items.reduce((a,i)=>a+i.q,0);
  b.innerHTML=`<div><b>🔔 Nuevo pedido #${o.id}</b>${V.length>1?' <span class="tag">+'+(V.length-1)+' más</span>':''}<div>${n} producto${n===1?'':'s'} · ${hm(o.t)} · Cliente: ${esc(fname(o))}</div></div><div class="row"><button class="btn sm" style="margin:0" id="tnewver" onclick="tSel=${o.id};tBanOff.push(${o.id});go('surtir')">Ver pedido</button><button class="btn sec sm" style="margin:0" aria-label="Cerrar" onclick="tBanOff.push(${o.id});liveNotify()">✕</button></div>`;return}
 if((role==='admin'||role==='dir')&&!locked()){const e=vivoEvents(1)[0];if(vivoSeen==null){vivoSeen=e?e.t:0;return}if(e&&e.t>vivoSeen){vivoSeen=e.t;toast('🛰️ '+evTxt(e))}}}

