{const _fp=fput,_fg=fget;fput=async(k,v)=>{await _fp(k,v);BK.upPhoto(k,v).catch(e=>console.warn('foto',e))};fget=async k=>{let v=await _fg(k);if(!v){try{v=await BK.getPhoto(k);if(v)await _fp(k,v)}catch(e){}}return v}}
